import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Usf Panel — VLESS Manager","description":"Premium VLESS tunnel and subscription manager: multi-user, Clash/v2ray/sing-box sync, one-command deploys to HF, Railway, Render, Fly, Koyeb.","frontmatter":{"title":"Usf Panel — VLESS Manager","description":"Premium VLESS tunnel and subscription manager: multi-user, Clash/v2ray/sing-box sync, one-command deploys to HF, Railway, Render, Fly, Koyeb."},"headers":[],"relativePath":"en/projects/usf-panel/index.md","filePath":"en/projects/usf-panel/index.md"}`),a={name:`en/projects/usf-panel/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="usf-panel-—-vless-manager" tabindex="-1">Usf Panel — VLESS Manager <a class="header-anchor" href="#usf-panel-—-vless-manager" aria-label="Permalink to “Usf Panel — VLESS Manager”">​</a></h1><p><strong>Usf Panel</strong> is the flagship of my networking work: a premium <strong>VLESS tunnel and subscription manager</strong> built as a single-file FastAPI application. It manages multi-user access, generates subscription links that Clash, v2ray and sing-box consume natively, and deploys to five platforms with one command each.</p><h2 id="why-another-panel" tabindex="-1">Why another panel <a class="header-anchor" href="#why-another-panel" aria-label="Permalink to “Why another panel”">​</a></h2><p>Existing panels are either enterprise-heavy (a full server farm to run one tunnel) or toy-grade (no user management, no stats, no resilience). Usf Panel takes the middle path seriously: one Python file you can read, a real admin panel with token + 2FA, per-user traffic accounting, and deploy targets matched to how censorship actually evolves — when one platform gets aggressive, you move in minutes, not days.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Detail</th></tr></thead><tbody><tr><td>Protocols</td><td>VLESS over WS/TLS, Reality-ready configs.</td></tr><tr><td>Subscriptions</td><td>Auto-generated links; Clash / v2ray / sing-box compatible.</td></tr><tr><td>Users</td><td>Multi-user with quotas, expiry and traffic stats.</td></tr><tr><td>Admin</td><td>Token + 2FA hardened panel, audit log.</td></tr><tr><td>Deploy</td><td>Hugging Face · Railway · Render · Fly.io · Koyeb — one command each.</td></tr></tbody></table><h2 id="the-family" tabindex="-1">The family <a class="header-anchor" href="#the-family" aria-label="Permalink to “The family”">​</a></h2><p>Usf Panel is not alone — it is the center of a family that covers every hosting philosophy: <strong>usf-edge</strong> runs the same idea entirely on Cloudflare Workers with KV state across 300+ PoPs; <strong>edge-pp</strong> extends edgetunnel with a full user-management panel; <strong>Render-usf</strong> targets Render with anti-blocking measures; <strong>Usf-Pnl-pro</strong> packages multi-platform deployment. The <a href="/Usf/en/about/networking/">networking section</a> explains why redundancy across platforms is a design requirement, not an option.</p><div class="warning custom-block"><p class="custom-block-title">A note on responsibility</p><p>These tools exist to restore access to information, not to break into anything. They ship with hardening — not exploits — and I expect users to respect the laws of their own jurisdictions.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};